QZ.load("econ", {"chapters":{"1":["1","The nature of the economic problem"],"2":["2","Factors of production"],"3":["3","Opportunity cost"],"4":["4","Production possibility curve (PPC) diagrams"],"6":["6","The role of markets in allocating resources"],"7":["7","Demand"],"8":["8","Supply"],"9":["9","Price determination"],"10":["10","Price changes"],"11":["11","Price elasticity of demand (PED)"],"12":["12","Price elasticity of supply (PES)"],"13":["13","Market economic system"],"14":["14","Market failure"],"15":["15","Mixed economic system"],"16":["16","Money and banking"],"17":["17","Households"],"18":["18","Workers"],"19":["19","Trade unions and bargaining power"],"20":["20","Firms"],"21":["21","Firms and production"],"22":["22","Firms' costs, revenue and objectives"],"23":["23","Types of markets: competitive and monopoly"],"25":["25","The macroeconomic aims of government"],"26":["26","Fiscal policy"],"27":["27","Monetary policy"],"28":["28","Supply-side policy"],"29":["29","Economic growth and recession"],"30":["30","Employment and unemployment"],"31":["31","Inflation and deflation"],"32":["32","Living standards"],"33":["33","Poverty"],"34":["34","Population"],"35":["35","Differences in economic development between countries"],"36":["36","International specialisation"],"37":["37","Free trade, globalisation and protection"],"38":["38","Foreign exchange rates"],"39":["39","Current account of the balance of payments"]},"topics":{"econ-form":["Formulas","Write the formula"],"econ-list":["Lists to recall","List them"]},"cards":[["n-e2-for-net-investment","econ-form",2,"Net investment","<div class=\"qn-fbox\">net investment = gross investment − depreciation</div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>gross investment = net investment + depreciation</b></p><p class=\"qn-fn\">Positive → the quantity of capital rises; negative → it falls.</p>",0,""],["n-e9-for-excess-demand","econ-form",9,"Excess demand","<div class=\"qn-fbox\">excess demand = quantity demanded − quantity supplied</div><p class=\"qn-fn\">At a price below equilibrium.</p>",0,""],["n-e9-for-excess-supply","econ-form",9,"Excess supply","<div class=\"qn-fbox\">excess supply = quantity supplied − quantity demanded</div><p class=\"qn-fn\">At a price above equilibrium.</p>",0,""],["n-e11-for-ped","econ-form",11,"PED","<div class=\"qn-fbox\">PED = <span class=\"frac\"><span class=\"nu\">% change in quantity demanded</span><span class=\"de\">% change in price</span></span></div><p class=\"qn-fn\">PED is <strong>negative</strong> (price and quantity demanded move in opposite directions). Give the answer to 2 decimal places with its minus sign.</p>",0,""],["n-e11-for-percentage-change","econ-form",11,"Percentage change","<div class=\"qn-fbox\">% change = <span class=\"frac\"><span class=\"nu\">change</span><span class=\"de\">original value</span></span> × 100</div><p class=\"qn-fn\">Always divide by the <strong>original</strong> (old) value.</p>",0,""],["n-e11-for-total-revenue-consumer-spe","econ-form",11,"Total revenue (= consumer spending)","<div class=\"qn-fbox\">total revenue = price × quantity sold</div>",0,""],["n-e12-for-pes","econ-form",12,"PES","<div class=\"qn-fbox\">PES = <span class=\"frac\"><span class=\"nu\">% change in quantity supplied</span><span class=\"de\">% change in price</span></span></div><p class=\"qn-fn\">PES is <strong>positive</strong> (price and quantity supplied move in the same direction).</p>",0,""],["n-e14-for-social-cost","econ-form",14,"Social cost","<div class=\"qn-fbox\">social cost = private cost + external cost</div>",0,""],["n-e14-for-social-benefit","econ-form",14,"Social benefit","<div class=\"qn-fbox\">social benefit = private benefit + external benefit</div>",0,""],["n-e17-for-apc","econ-form",17,"APC","<div class=\"qn-fbox\">APC = <span class=\"frac\"><span class=\"nu\">consumption</span><span class=\"de\">disposable income</span></span></div>",0,""],["n-e17-for-aps","econ-form",17,"APS","<div class=\"qn-fbox\">APS = <span class=\"frac\"><span class=\"nu\">saving</span><span class=\"de\">disposable income</span></span></div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>APC + APS = 1</b></p><p class=\"qn-fn\">e.g. disposable income $2000, saving $300 → APS = 0.15, APC = 0.85.</p>",0,""],["n-e21-for-labour-productivity","econ-form",21,"Labour productivity","<div class=\"qn-fbox\">labour productivity = <span class=\"frac\"><span class=\"nu\">total output</span><span class=\"de\">number of workers</span></span></div><p class=\"qn-fn\">Or output ÷ number of <strong>worker-hours</strong>. e.g. 50 workers make 2000 shirts a day → 40 shirts per worker per day.</p>",0,""],["n-e22-for-total-cost","econ-form",22,"Total cost","<div class=\"qn-fbox\">TC = FC + VC</div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>FC = TC − VC</b> · <b>VC = TC − FC</b></p>",0,""],["n-e22-for-average-total-cost","econ-form",22,"Average total cost","<div class=\"qn-fbox\">ATC = <span class=\"frac\"><span class=\"nu\">TC</span><span class=\"de\">output</span></span></div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>ATC = AFC + AVC</b> · <b>TC = ATC × output</b></p>",0,""],["n-e22-for-average-fixed-cost","econ-form",22,"Average fixed cost","<div class=\"qn-fbox\">AFC = <span class=\"frac\"><span class=\"nu\">FC</span><span class=\"de\">output</span></span></div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>FC = AFC × output</b></p>",0,""],["n-e22-for-average-variable-cost","econ-form",22,"Average variable cost","<div class=\"qn-fbox\">AVC = <span class=\"frac\"><span class=\"nu\">VC</span><span class=\"de\">output</span></span></div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>VC = AVC × output</b></p>",0,""],["n-e22-for-total-revenue","econ-form",22,"Total revenue","<div class=\"qn-fbox\">TR = price × quantity sold</div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>AR = TR ÷ quantity = price</b></p>",0,""],["n-e22-for-profit","econ-form",22,"Profit","<div class=\"qn-fbox\">profit = total revenue − total cost</div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>total cost = total revenue − profit</b></p><p class=\"qn-fn\">A profit is made when <strong>revenue &gt; cost</strong>; a loss when cost &gt; revenue.</p>",0,""],["n-e26-for-budget-balance","econ-form",26,"Budget balance","<div class=\"qn-fbox\">budget balance = government revenue − government spending</div><p class=\"qn-fn\">Positive → <strong>surplus</strong>; negative → <strong>deficit</strong>. e.g. revenue $400 bn, spending $460 bn → deficit of $60 bn.</p>",0,""],["n-e26-for-budget-deficit-as-of-gdp","econ-form",26,"Budget deficit as % of GDP","<div class=\"qn-fbox\"><span class=\"frac\"><span class=\"nu\">budget deficit</span><span class=\"de\">GDP</span></span> × 100</div><p class=\"qn-fn\">e.g. deficit $60 bn, GDP $2000 bn → 3% of GDP.</p>",0,""],["n-e26-for-average-tax-rate","econ-form",26,"Average tax rate","<div class=\"qn-fbox\"><span class=\"frac\"><span class=\"nu\">tax paid</span><span class=\"de\">income</span></span> × 100</div><p class=\"qn-fn\">Use it to classify a tax: rises with income → progressive; same → proportional; falls → regressive.</p>",0,""],["n-e29-for-economic-growth-rate","econ-form",29,"Economic growth rate","<div class=\"qn-fbox\">growth rate = <span class=\"frac\"><span class=\"nu\">real GDP this year − real GDP last year</span><span class=\"de\">real GDP last year</span></span> × 100</div><p class=\"qn-fn\">e.g. real GDP rises from $500 bn to $520 bn → growth = 20 ÷ 500 × 100 = <strong>4%</strong>.</p>",0,""],["n-e29-for-real-gdp-per-head","econ-form",29,"Real GDP per head","<div class=\"qn-fbox\">real GDP per head = <span class=\"frac\"><span class=\"nu\">real GDP</span><span class=\"de\">population</span></span></div>",0,""],["n-e30-for-unemployment-rate","econ-form",30,"Unemployment rate","<div class=\"qn-fbox\">unemployment rate = <span class=\"frac\"><span class=\"nu\">number unemployed</span><span class=\"de\">labour force</span></span> × 100</div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>labour force = employed + unemployed</b></p><p class=\"qn-fn\">e.g. 2 million unemployed, 38 million employed → labour force 40 million → rate = <strong>5%</strong>. Divide by the <strong>labour force</strong>, not the whole population.</p>",0,""],["n-e31-for-inflation-rate","econ-form",31,"Inflation rate","<div class=\"qn-fbox\">inflation rate = <span class=\"frac\"><span class=\"nu\">CPI this year − CPI last year</span><span class=\"de\">CPI last year</span></span> × 100</div><p class=\"qn-fn\">e.g. CPI rises from 120 to 126 → 6 ÷ 120 × 100 = <strong>5%</strong>.</p>",0,""],["n-e31-for-weighted-price-index","econ-form",31,"Weighted price index","<div class=\"qn-fbox\">weighted index = <span class=\"frac\"><span class=\"nu\">Σ(weight × price index)</span><span class=\"de\">Σ weights</span></span></div><p class=\"qn-fn\">Price index of each item × its weight, add them up, divide by the total of the weights (often 100 or 1000). See the worked example in 31.2.</p>",0,""],["n-e32-for-real-gdp-per-head","econ-form",32,"Real GDP per head","<div class=\"qn-fbox\">real GDP per head = <span class=\"frac\"><span class=\"nu\">real GDP</span><span class=\"de\">population</span></span></div><p class=\"qn-fn\">e.g. real GDP $3000 bn, population 1.5 bn → $2000 per head.</p>",0,""],["n-e34-for-population-growth","econ-form",34,"Population growth","<div class=\"qn-fbox\">population change = births − deaths + net migration</div><p class=\"qn-fn\">Births − deaths is the <strong>natural increase</strong>. Net migration = immigration − emigration.</p>",0,""],["n-e34-for-dependency-ratio","econ-form",34,"Dependency ratio","<div class=\"qn-fbox\">dependency ratio = <span class=\"frac\"><span class=\"nu\">number of dependants (aged 0–14 and 65+)</span><span class=\"de\">working-age population (15–64)</span></span> × 100</div><p class=\"qn-fn\">e.g. 40 million dependants, 80 million of working age → ratio = 50.</p>",0,""],["n-e39-for-current-account-balance","econ-form",39,"Current account balance","<div class=\"qn-fbox\">current account balance = trade in goods balance + trade in services balance + primary income balance + secondary income balance</div>",0,""],["n-e39-for-balance-of-trade-in-goods","econ-form",39,"Balance of trade in goods","<div class=\"qn-fbox\">trade in goods balance = exports of goods − imports of goods</div><p class=\"qn-fn\">The same method (inflows − outflows) works for services, primary and secondary income.</p>",0,""],["n-e2-list-the-four-factors-of-produc","econ-list",2,"The four factors of production and the reward to each?","<ul>\n<li><strong>Land</strong> → rent</li>\n<li><strong>Labour</strong> → wages</li>\n<li><strong>Capital</strong> → interest</li>\n<li><strong>Enterprise</strong> → profit</li>\n</ul>",0,"List them"],["n-e6-list-the-three-basic-economic-q","econ-list",6,"The three basic economic questions?","<ul>\n<li><strong>What</strong> to produce</li>\n<li><strong>How</strong> to produce</li>\n<li><strong>For whom</strong> to produce</li>\n</ul>",0,"List them"],["n-e7-list-conditions-of-demand-what","econ-list",7,"Conditions of demand: what shifts the demand curve?","<ul>\n<li><strong>Income</strong> (normal and inferior goods)</li>\n<li><strong>Prices of substitutes and complements</strong></li>\n<li><strong>Advertising</strong></li>\n<li><strong>Population</strong> (size and age structure)</li>\n<li><strong>Fashion and tastes</strong></li>\n<li>Weather, expectations of future prices, special events</li>\n</ul>",0,"List them"],["n-e8-list-conditions-of-supply-what","econ-list",8,"Conditions of supply: what shifts the supply curve?","<ul>\n<li><strong>Costs of production</strong> (and productivity)</li>\n<li><strong>Technology</strong></li>\n<li><strong>Indirect taxes</strong></li>\n<li><strong>Subsidies</strong></li>\n<li><strong>Weather</strong> and health of crops and livestock</li>\n<li><strong>Prices of other products</strong> (competitive and joint supply)</li>\n<li><strong>Disasters and wars</strong></li>\n<li><strong>Discoveries and depletion</strong> of resources</li>\n</ul>",0,"List them"],["n-e11-list-ped-values-what-does-each","econ-list",11,"PED values: what does each one mean?","<ul>\n<li><strong>0</strong> → perfectly inelastic</li>\n<li><strong>between 0 and 1</strong> → inelastic</li>\n<li><strong>1</strong> → unitary</li>\n<li><strong>greater than 1</strong> → elastic</li>\n<li><strong>infinity</strong> → perfectly elastic</li>\n</ul>\n<p>(ignore the minus sign for the size)</p>",0,"List them"],["n-e11-list-determinants-of-ped-demand","econ-list",11,"Determinants of PED: demand is more elastic when…?","<ul>\n<li>many close <strong>substitutes</strong></li>\n<li>a large <strong>proportion of income</strong></li>\n<li>a <strong>luxury</strong>, not a necessity</li>\n<li><strong>not habit-forming</strong></li>\n<li>the market is <strong>narrowly defined</strong></li>\n<li>the <strong>time period is long</strong></li>\n</ul>",0,"List them"],["n-e11-list-a-price-rise-what-happens","econ-list",11,"A price rise: what happens to revenue if demand is inelastic, elastic, unitary?","<ul>\n<li><strong>Inelastic</strong> → revenue <strong>rises</strong></li>\n<li><strong>Elastic</strong> → revenue <strong>falls</strong></li>\n<li><strong>Unitary</strong> → revenue <strong>unchanged</strong></li>\n</ul>",0,"List them"],["n-e12-list-straight-line-supply-curve","econ-list",12,"Straight-line supply curves: the shape for each PES?","<ul>\n<li><strong>0</strong> → vertical</li>\n<li><strong>inelastic</strong> → starts from the <strong>quantity axis</strong></li>\n<li><strong>unitary</strong> → passes through the <strong>origin</strong></li>\n<li><strong>elastic</strong> → starts from the <strong>price axis</strong></li>\n<li><strong>infinity</strong> → horizontal</li>\n</ul>",0,"List them"],["n-e12-list-determinants-of-pes-supply","econ-list",12,"Determinants of PES: supply is more elastic when…?","<ul>\n<li>production is <strong>quick</strong></li>\n<li>there is <strong>spare capacity</strong></li>\n<li><strong>stocks</strong> can be held (product can be stored)</li>\n<li>factors of production are <strong>mobile and available</strong></li>\n<li><strong>costs of changing output</strong> are low</li>\n<li>the <strong>time period is long</strong></li>\n</ul>",0,"List them"],["n-e14-list-the-two-features-of-a-publ","econ-list",14,"The two features of a public good?","<ul>\n<li><strong>Non-excludable</strong> (free riders can't be stopped)</li>\n<li><strong>Non-rival</strong> (one person's use doesn't reduce the amount for others)</li>\n</ul>",0,"List them"],["n-e14-list-the-four-consequences-of-m","econ-list",14,"The four consequences of market failure in the syllabus?","<ul>\n<li><strong>Over-consumption</strong> of demerit goods and goods with external costs</li>\n<li><strong>Under-consumption</strong> of merit goods and goods with external benefits</li>\n<li><strong>Non-provision</strong> of public goods</li>\n<li><strong>Restricted supply causing higher prices</strong> under a monopoly</li>\n</ul>",0,"List them"],["n-e15-list-government-measures-to-cor","econ-list",15,"Government measures to correct market failure (syllabus list)?","<ul>\n<li><strong>Maximum and minimum prices</strong></li>\n<li><strong>Indirect taxation</strong></li>\n<li><strong>Subsidies</strong></li>\n<li><strong>Regulation</strong></li>\n<li><strong>Privatisation</strong></li>\n<li><strong>Nationalisation</strong></li>\n<li><strong>Direct provision</strong> of goods and services</li>\n<li><strong>Quotas</strong> (e.g. on extracting natural resources)</li>\n</ul>",0,"List them"],["n-e15-list-maximum-and-minimum-prices","econ-list",15,"Maximum and minimum prices: where are they set, and what do they cause?","<ul>\n<li><strong>Maximum price</strong> → set <strong>below</strong> equilibrium → <strong>shortage</strong> (excess demand)</li>\n<li><strong>Minimum price</strong> → set <strong>above</strong> equilibrium → <strong>surplus</strong> (excess supply)</li>\n</ul>",0,"List them"],["n-e16-list-the-four-functions-of-mone","econ-list",16,"The four functions of money?","<ul>\n<li><strong>Medium of exchange</strong></li>\n<li><strong>Store of value</strong></li>\n<li><strong>Unit of account</strong></li>\n<li><strong>Standard of deferred payment</strong></li>\n</ul>",0,"List them"],["n-e16-list-the-characteristics-of-mon","econ-list",16,"The characteristics of money?","<ul>\n<li><strong>Generally acceptable</strong></li>\n<li><strong>Durable</strong></li>\n<li><strong>Portable</strong></li>\n<li><strong>Divisible</strong></li>\n<li><strong>Homogeneous</strong> (all units the same)</li>\n<li><strong>Recognisable</strong> (hard to forge)</li>\n<li><strong>Limited in supply</strong></li>\n</ul>",0,"List them"],["n-e16-list-the-three-aims-of-a-commer","econ-list",16,"The three aims of a commercial bank?","<ul>\n<li><strong>Profit</strong></li>\n<li><strong>Liquidity</strong></li>\n<li><strong>Security</strong></li>\n</ul>",0,"List them"],["n-e16-list-roles-of-a-central-bank","econ-list",16,"Roles of a central bank?","<ul>\n<li>Banker to the <strong>government</strong></li>\n<li>Banker to the <strong>commercial banks</strong></li>\n<li><strong>Lender of last resort</strong></li>\n<li>Manages the <strong>national debt</strong></li>\n<li>Holds <strong>gold and foreign currency reserves</strong></li>\n<li><strong>Issues notes</strong></li>\n<li>Runs <strong>monetary policy</strong></li>\n<li><strong>Supervises</strong> the banking system</li>\n<li><strong>Represents</strong> the government (e.g. at the IMF)</li>\n</ul>",0,"List them"],["n-e17-list-the-five-influences-on-hou","econ-list",17,"The five influences on households&#x27; spending, saving and borrowing (2027)?","<ul>\n<li><strong>Income</strong></li>\n<li><strong>Rate of interest</strong></li>\n<li><strong>Confidence</strong></li>\n<li><strong>Age</strong></li>\n<li><strong>Culture</strong></li>\n</ul>",0,"List them"],["n-e18-list-the-four-reasons-for-diffe","econ-list",18,"The four reasons for differences in wages (syllabus)?","<ul>\n<li><strong>Demand for and supply of labour</strong></li>\n<li><strong>Relative bargaining strength</strong></li>\n<li><strong>Discrimination</strong> (e.g. male/female)</li>\n<li><strong>Government policy</strong></li>\n</ul>",0,"List them"],["n-e20-list-the-three-types-of-merger","econ-list",20,"The three types of merger?","<ul>\n<li><strong>Horizontal</strong> — same product, same stage of production</li>\n<li><strong>Vertical</strong> — different stages of the same product (<strong>backwards</strong> to a supplier, <strong>forwards</strong> to an outlet)</li>\n<li><strong>Conglomerate</strong> — different, unrelated products</li>\n</ul>",0,"List them"],["n-e20-list-the-eight-internal-economi","econ-list",20,"The eight internal economies of scale?","<ul>\n<li><strong>Buying</strong> (purchasing)</li>\n<li><strong>Selling</strong> (marketing)</li>\n<li><strong>Managerial</strong></li>\n<li><strong>Labour</strong> (specialisation)</li>\n<li><strong>Financial</strong></li>\n<li><strong>Technical</strong></li>\n<li><strong>Research and development</strong></li>\n<li><strong>Risk-bearing</strong></li>\n</ul>",0,"List them"],["n-e20-list-the-three-internal-disecon","econ-list",20,"The three internal diseconomies of scale?","<ul>\n<li><strong>Difficulty controlling</strong> the firm</li>\n<li><strong>Communication problems</strong></li>\n<li><strong>Poor industrial relations</strong></li>\n</ul>",0,"List them"],["n-e20-list-external-economies-of-scal","econ-list",20,"External economies of scale?","<ul>\n<li>A <strong>skilled labour force</strong></li>\n<li>A <strong>good reputation</strong> of the area</li>\n<li><strong>Specialist suppliers</strong></li>\n<li><strong>Specialist services</strong></li>\n<li><strong>Specialist markets</strong></li>\n<li><strong>Improved infrastructure</strong></li>\n</ul>",0,"List them"],["n-e21-list-the-four-influences-on-the","econ-list",21,"The four influences on the demand for factors of production (syllabus)?","<ul>\n<li><strong>Demand for the product</strong></li>\n<li><strong>Price</strong> of the different factors</li>\n<li><strong>Availability</strong></li>\n<li><strong>Productivity</strong></li>\n</ul>",0,"List them"],["n-e22-list-the-four-objectives-of-fir","econ-list",22,"The four objectives of firms (syllabus)?","<ul>\n<li><strong>Survival</strong></li>\n<li><strong>Growth</strong></li>\n<li><strong>Social welfare</strong></li>\n<li><strong>Profit maximisation</strong></li>\n</ul>",0,"List them"],["n-e23-list-effect-of-many-firms-a-com","econ-list",23,"Effect of many firms (a competitive market) on price, quality, choice and profit?","<ul>\n<li><strong>Price</strong> → low</li>\n<li><strong>Quality</strong> → high</li>\n<li><strong>Choice</strong> → wide</li>\n<li><strong>Profit</strong> → low (normal profit in the long run)</li>\n</ul>",0,"List them"],["n-e23-list-effect-of-one-firm-a-monop","econ-list",23,"Effect of one firm (a monopoly) on price, quality, choice and profit?","<ul>\n<li><strong>Price</strong> → higher</li>\n<li><strong>Quality</strong> → may be lower</li>\n<li><strong>Choice</strong> → less</li>\n<li><strong>Profit</strong> → high (supernormal), can last</li>\n</ul>",0,"List them"],["n-e25-list-the-six-macroeconomic-aims","econ-list",25,"The six macroeconomic aims of government (2027)?","<ul>\n<li><strong>Economic growth</strong></li>\n<li><strong>Full employment / low unemployment</strong></li>\n<li><strong>Stable prices / low inflation</strong></li>\n<li><strong>Balance of payments stability</strong></li>\n<li><strong>Redistribution of income</strong></li>\n<li><strong>Environmental sustainability</strong></li>\n</ul>",0,"List them"],["n-e25-list-the-three-conflicts-betwee","econ-list",25,"The three conflicts between aims named in the syllabus?","<ul>\n<li><strong>Full employment</strong> vs <strong>stable prices</strong></li>\n<li><strong>Economic growth</strong> vs <strong>environmental sustainability</strong></li>\n<li><strong>Full employment</strong> vs <strong>balance of payments stability</strong></li>\n</ul>",0,"List them"],["n-e26-list-the-six-reasons-for-taxati","econ-list",26,"The six reasons for taxation (syllabus)?","<ul>\n<li><strong>Raising revenue</strong></li>\n<li><strong>Discouraging consumption of demerit goods</strong></li>\n<li><strong>Reducing imports</strong></li>\n<li><strong>Redistributing income</strong></li>\n<li><strong>Influencing total demand</strong></li>\n<li><strong>Encouraging environmental sustainability</strong></li>\n</ul>",0,"List them"],["n-e26-list-examples-of-direct-and-ind","econ-list",26,"Examples of direct and indirect taxes?","<ul>\n<li><strong>Direct:</strong> income tax, corporation tax, capital gains tax, inheritance tax</li>\n<li><strong>Indirect:</strong> VAT / GST (sales tax), excise duties, customs duties (tariffs)</li>\n</ul>",0,"List them"],["n-e26-list-examples-of-a-progressive","econ-list",26,"Examples of a progressive, a proportional and a regressive tax?","<ul>\n<li><strong>Progressive:</strong> income tax with higher rates on higher incomes</li>\n<li><strong>Proportional:</strong> a flat-rate tax (same % for all)</li>\n<li><strong>Regressive:</strong> indirect taxes on necessities; a fixed amount per person</li>\n</ul>",0,"List them"],["n-e27-list-the-three-monetary-policy","econ-list",27,"The three monetary policy measures?","<ul>\n<li><strong>Interest rate</strong></li>\n<li><strong>Money supply</strong></li>\n<li><strong>Foreign exchange rate</strong></li>\n</ul>",0,"List them"],["n-e28-list-the-seven-supply-side-poli","econ-list",28,"The seven supply-side policy measures (2027)?","<ul>\n<li><strong>Education and training</strong></li>\n<li><strong>Infrastructure spending</strong></li>\n<li><strong>Labour market reforms</strong></li>\n<li><strong>Lower direct taxes</strong></li>\n<li><strong>Deregulation</strong></li>\n<li><strong>Improving incentives to work and invest</strong></li>\n<li><strong>Privatisation</strong></li>\n</ul>",0,"List them"],["n-e29-list-the-three-causes-of-econom","econ-list",29,"The three causes of economic growth (syllabus wording)?","<ul>\n<li>An increase in <strong>total demand</strong></li>\n<li>An increase in the <strong>quantity</strong> of resources</li>\n<li>An increase in the <strong>quality</strong> of resources</li>\n</ul>",0,"List them"],["n-e29-list-recession-the-four-groups","econ-list",29,"Recession: the four groups whose consequences you must know?","<ul>\n<li><strong>Consumers</strong></li>\n<li><strong>Workers</strong></li>\n<li><strong>Producers / firms</strong></li>\n<li><strong>The government</strong></li>\n</ul>",0,"List them"],["n-e30-list-the-four-types-causes-of-u","econ-list",30,"The four types (causes) of unemployment?","<ul>\n<li><strong>Frictional</strong></li>\n<li><strong>Structural</strong></li>\n<li><strong>Cyclical</strong></li>\n<li><strong>Seasonal</strong></li>\n</ul>",0,"List them"],["n-e30-list-labour-force-survey-ilo-wh","econ-list",30,"Labour force survey (ILO): who counts as unemployed?","<ul>\n<li><strong>Without a job</strong></li>\n<li><strong>Looked for work in the past four weeks</strong></li>\n<li><strong>Able to start within two weeks</strong></li>\n</ul>",0,"List them"],["n-e31-list-the-steps-in-constructing","econ-list",31,"The steps in constructing the CPI?","<ol>\n<li>Choose a <strong>base year</strong> (= 100)</li>\n<li>Survey how households spend → <strong>weights</strong></li>\n<li>Collect the <strong>prices</strong> of a representative <strong>basket</strong></li>\n<li>Calculate the <strong>weighted price index</strong></li>\n</ol>",0,"List them"],["n-e31-list-the-two-causes-of-inflatio","econ-list",31,"The two causes of inflation (syllabus)?","<ul>\n<li><strong>Demand-pull</strong></li>\n<li><strong>Cost-push</strong></li>\n</ul>",0,"List them"],["n-e31-list-inflation-who-gains-and-wh","econ-list",31,"Inflation: who gains and who loses — savers, lenders, borrowers?","<ul>\n<li><strong>Savers</strong> lose (if inflation is above the interest rate)</li>\n<li><strong>Lenders</strong> lose</li>\n<li><strong>Borrowers</strong> gain (real burden of debt falls)</li>\n</ul>",0,"List them"],["n-e32-list-the-three-components-of-th","econ-list",32,"The three components of the HDI?","<ul>\n<li><strong>Health</strong> — life expectancy at birth</li>\n<li><strong>Education</strong> — mean and expected years of schooling</li>\n<li><strong>Income</strong> — GNI per head (at PPP)</li>\n</ul>",0,"List them"],["n-e33-list-the-five-causes-of-poverty","econ-list",33,"The five causes of poverty (syllabus)?","<ul>\n<li><strong>Unemployment</strong></li>\n<li><strong>Low wages</strong></li>\n<li><strong>Illness</strong></li>\n<li><strong>Age</strong></li>\n<li><strong>Environmental factors</strong></li>\n</ul>",0,"List them"],["n-e33-list-the-six-policies-to-allevi","econ-list",33,"The six policies to alleviate poverty (syllabus)?","<ul>\n<li><strong>Promoting economic growth</strong></li>\n<li><strong>Improved education</strong></li>\n<li><strong>Improved healthcare provision</strong></li>\n<li><strong>More generous state benefits</strong></li>\n<li><strong>Progressive taxation</strong></li>\n<li><strong>National minimum wage</strong></li>\n</ul>",0,"List them"],["n-e34-list-the-three-causes-of-popula","econ-list",34,"The three causes of population change?","<ul>\n<li><strong>Births</strong> (birth rate)</li>\n<li><strong>Deaths</strong> (death rate)</li>\n<li><strong>Net migration</strong></li>\n</ul>",0,"List them"],["n-e34-list-consequences-of-an-ageing","econ-list",34,"Consequences of an ageing population?","<ul>\n<li><strong>Rising dependency ratio</strong></li>\n<li><strong>Older, less mobile labour force</strong></li>\n<li>More demand for <strong>healthcare</strong> and <strong>welfare services</strong></li>\n<li>Higher cost of <strong>pensions</strong></li>\n<li><strong>Changing pattern of demand</strong></li>\n</ul>",0,"List them"],["n-e35-list-the-eight-causes-of-differ","econ-list",35,"The eight causes of differences in development between countries (syllabus)?","<ul>\n<li><strong>Income</strong></li>\n<li><strong>Productivity</strong></li>\n<li><strong>Population growth</strong></li>\n<li><strong>Size of primary, secondary and tertiary sectors</strong></li>\n<li><strong>Saving and investment</strong></li>\n<li><strong>Education</strong></li>\n<li><strong>Healthcare</strong></li>\n<li><strong>Natural resources</strong></li>\n</ul>",0,"List them"],["n-e35-list-hdi-levels-of-human-develo","econ-list",35,"HDI levels of human development?","<ul>\n<li><strong>Very high</strong> — 0.800 and above</li>\n<li><strong>High</strong> — 0.700–0.799</li>\n<li><strong>Medium</strong> — 0.550–0.699</li>\n<li><strong>Low</strong> — below 0.550</li>\n</ul>",0,"List them"],["n-e37-list-the-four-causes-of-changes","econ-list",37,"The four causes of changes in globalisation (syllabus)?","<ul>\n<li>Changes in <strong>trade restrictions</strong></li>\n<li>Changes in <strong>transport costs</strong></li>\n<li>Changes in <strong>communication costs</strong></li>\n<li><strong>Movement of MNCs</strong></li>\n</ul>",0,"List them"],["n-e37-list-the-six-areas-affected-by","econ-list",37,"The six areas affected by changes in globalisation (syllabus)?","<ul>\n<li><strong>International trade</strong></li>\n<li><strong>Competition</strong></li>\n<li><strong>The environment</strong></li>\n<li><strong>Migration</strong></li>\n<li><strong>Income distribution</strong></li>\n<li><strong>Economic development</strong></li>\n</ul>",0,"List them"],["n-e37-list-the-four-methods-of-protec","econ-list",37,"The four methods of protection (syllabus)?","<ul>\n<li><strong>Tariffs</strong></li>\n<li><strong>Import quotas</strong></li>\n<li><strong>Subsidies</strong></li>\n<li><strong>Embargoes</strong></li>\n</ul>",0,"List them"],["n-e37-list-the-eight-reasons-for-trad","econ-list",37,"The eight reasons for trade restrictions (syllabus)?","<ul>\n<li>Protect <strong>infant (sunrise)</strong> industries</li>\n<li>Protect <strong>declining (sunset)</strong> industries</li>\n<li>Protect <strong>strategic</strong> industries</li>\n<li>Avoid <strong>dumping</strong></li>\n<li>Reduce a <strong>current account deficit</strong></li>\n<li>Raise <strong>tax revenue</strong></li>\n<li>Restrict imports of <strong>demerit goods</strong></li>\n<li>Promote <strong>environmental sustainability</strong></li>\n</ul>",0,"List them"],["n-e38-list-the-six-reasons-for-buying","econ-list",38,"The six reasons for buying and selling foreign currencies (syllabus)?","<ul>\n<li><strong>Trade</strong> in goods and services</li>\n<li><strong>Speculation</strong></li>\n<li><strong>Government intervention</strong></li>\n<li>Payment of <strong>profit, interest and dividends</strong></li>\n<li><strong>Workers' remittances</strong></li>\n<li><strong>Investment</strong> in capital goods between countries</li>\n</ul>",0,"List them"],["n-e38-list-the-three-causes-of-exchan","econ-list",38,"The three causes of exchange-rate fluctuations (syllabus)?","<ul>\n<li>Changes in <strong>demand for exports and imports</strong></li>\n<li>Changes in the <strong>interest rate</strong></li>\n<li><strong>Speculation</strong></li>\n</ul>",0,"List them"],["n-e38-list-an-appreciation-effect-on","econ-list",38,"An appreciation: effect on export and import prices?","<ul>\n<li><strong>Exports dearer</strong> (in foreign currency)</li>\n<li><strong>Imports cheaper</strong> (in domestic currency)</li>\n</ul>\n<p>A depreciation does the opposite.</p>",0,"List them"],["n-e39-list-the-four-components-of-the","econ-list",39,"The four components of the current account?","<ul>\n<li><strong>Trade in goods</strong></li>\n<li><strong>Trade in services</strong></li>\n<li><strong>Primary income</strong></li>\n<li><strong>Secondary income</strong></li>\n</ul>",0,"List them"],["n-e39-list-a-current-account-deficit","econ-list",39,"A current account deficit: the four things whose impact you must know?","<ul>\n<li><strong>GDP</strong></li>\n<li><strong>Employment</strong></li>\n<li><strong>Inflation</strong></li>\n<li><strong>Foreign exchange rate</strong></li>\n</ul>",0,"List them"]],"defs":[["d-e1-basic-economic-problem",1,"Basic economic problem","<p>The basic economic problem is that resources are finite (limited) but wants are infinite (unlimited), so choices have to be made.</p>","<p>Because of it every consumer, worker, firm and government has to decide what to have and what to go without.</p>",0],["d-e1-scarcity",1,"Scarcity","<p>A situation where there are not enough resources to satisfy everyone's wants.</p>","<p>Scarcity exists in <strong>every</strong> country, rich or poor, and for every person: even a very rich person has limited <strong>time</strong>. Scarcity → choice → opportunity cost (Chapter 3).</p>",0],["d-e1-economic-good",1,"Economic good","<p>A product that requires resources to produce it and therefore has an opportunity cost.</p>","<p>e.g. cars, bottled water, education, a mobile phone. It is still an economic good if it is given away free (a free school meal used resources).</p>",0],["d-e1-free-good",1,"Free good","<p>A product that does not require any resources to make it and so has no opportunity cost.</p>","<p>e.g. air, sunlight, sea water in the sea, sand in a desert. There is enough for everyone and using it does not stop anyone else using it.</p>",0],["d-e2-factors-of-production",2,"Factors of production","<p>The economic resources used to produce goods and services: land, labour, capital and enterprise.</p>","<p>Their rewards: <strong>land → rent, labour → wages, capital → interest, enterprise → profit</strong>.</p>",0],["d-e2-land",2,"Land","<p>Natural resources (gifts of nature) used in production.</p>","<p>e.g. the land surface, minerals and oil, forests, rivers, fish in the sea. Reward: <strong>rent</strong>.</p>",0],["d-e2-labour",2,"Labour","<p>Human effort, physical and mental, used in producing goods and services.</p>","<p>e.g. factory workers, teachers, doctors. Its quality depends on <strong>human capital</strong> — the education, training, skills and experience of workers. Reward: <strong>wages</strong>.</p>",0],["d-e2-capital",2,"Capital","<p>Human-made goods used to produce other goods and services.</p>","<p>e.g. machinery, tools, factories, offices, delivery vans, computers. Also called <strong>capital goods</strong>. Reward: <strong>interest</strong>. In economics capital does <strong>not</strong> mean money.</p>",0],["d-e2-enterprise",2,"Enterprise","<p>The willingness and ability to bear the risks of a business and to make the key decisions, organising the other factors of production.</p>","<p>Reward: <strong>profit</strong> (and the risk of a loss).</p>",0],["d-e2-productivity",2,"Productivity","<p>Output per factor of production per period of time.</p><p>Labour productivity: output per worker per hour.</p>","<p>Higher productivity means more output from the same resources. Full notes on production vs productivity in 21.3.</p>",0],["d-e2-mobility-of-labour",2,"Mobility of labour","<p>The ability of workers to change occupation (occupational mobility) or to move to work in a different area (geographical mobility).</p>","<p>See the difference table below and 2.2.</p>",0],["d-e3-opportunity-cost",3,"Opportunity cost","<p>The best alternative forgone (given up) when a choice is made.</p>","<p>Only the <strong>next best</strong> alternative counts, not every alternative. e.g. a student spends an evening revising Economics instead of going to the cinema → the opportunity cost is the cinema trip.</p>",0],["d-e4-production-possibility-curve-p",4,"Production possibility curve (PPC)","<p>A curve that shows the maximum output of two types of products, and the combinations of them, that can be produced with existing resources and technology.</p>","<p>Also called the production possibility frontier or boundary.</p>",0],["d-e6-market",6,"Market","<p>An arrangement which brings buyers and sellers into contact with each other to exchange products.</p>","<p>It does not need a building. Examples: a vegetable market, a shopping mall, online markets (Amazon, Flipkart), the labour market, the foreign exchange market, the stock market.</p>",0],["d-e7-demand",7,"Demand","<p>The willingness and ability to buy a product at a given price over a given time period.</p>","<p>This is <strong>effective demand</strong>: wanting a product is not enough — the buyer must be <strong>able to pay</strong> for it.</p>",0],["d-e8-supply",8,"Supply","<p>The willingness and ability to sell a product at a given price over a given time period.</p>","",0],["d-e9-market-equilibrium",9,"Market equilibrium","<p>A situation where demand and supply are equal at the current price.</p>","<p>There is no pressure for the price to change.</p>",0],["d-e9-market-disequilibrium",9,"Market disequilibrium","<p>A situation where demand and supply are not equal at the current price.</p>","<p>There is either a shortage or a surplus, so the price will change.</p>",0],["d-e11-price-elasticity-of-demand-ped",11,"Price elasticity of demand (PED)","<p>A measure of the responsiveness of the quantity demanded to a change in price.</p>","<p>PED = % change in quantity demanded ÷ % change in price.</p>",0],["d-e11-elastic-demand",11,"Elastic demand","<p>When the quantity demanded changes by a greater percentage than the change in price.</p>","<p>PED is <strong>greater than 1</strong> (ignoring the minus sign), e.g. −2.5.</p>",0],["d-e11-inelastic-demand",11,"Inelastic demand","<p>When the quantity demanded changes by a smaller percentage than the change in price.</p>","<p>PED is <strong>between 0 and 1</strong> (ignoring the sign), e.g. −0.4.</p>",0],["d-e11-unitary-elastic-demand",11,"Unitary elastic demand","<p>When the quantity demanded changes by the same percentage as the change in price.</p>","<p>PED = <strong>−1</strong>. Total spending (revenue) does not change when the price changes.</p>",0],["d-e11-perfectly-elastic-demand",11,"Perfectly elastic demand","<p>When a change in price causes the quantity demanded to change completely (fall to zero).</p>","<p>PED = <strong>infinity</strong>. Horizontal demand curve.</p>",0],["d-e11-perfectly-inelastic-demand",11,"Perfectly inelastic demand","<p>When a change in price has no effect on the quantity demanded.</p>","<p>PED = <strong>0</strong>. Vertical demand curve.</p>",0],["d-e12-price-elasticity-of-supply-pes",12,"Price elasticity of supply (PES)","<p>A measure of the responsiveness of the quantity supplied to a change in price.</p>","<p>PES = % change in quantity supplied ÷ % change in price.</p>",0],["d-e12-elastic-supply",12,"Elastic supply","<p>When the quantity supplied changes by a greater percentage than the change in price.</p>","<p>PES <strong>greater than 1</strong>.</p>",0],["d-e12-inelastic-supply",12,"Inelastic supply","<p>When the quantity supplied changes by a smaller percentage than the change in price.</p>","<p>PES <strong>between 0 and 1</strong>.</p>",0],["d-e12-unitary-elastic-supply",12,"Unitary elastic supply","<p>When the quantity supplied changes by the same percentage as the change in price.</p>","<p>PES = <strong>1</strong>.</p>",0],["d-e12-perfectly-elastic-supply",12,"Perfectly elastic supply","<p>When a change in price causes a complete change in the quantity supplied.</p>","<p>PES = <strong>infinity</strong>; horizontal supply curve — firms will supply any amount at that price but nothing below it.</p>",0],["d-e12-perfectly-inelastic-supply",12,"Perfectly inelastic supply","<p>When a change in price has no effect on the quantity supplied.</p>","<p>PES = <strong>0</strong>; vertical supply curve (e.g. seats in a stadium on match day).</p>",0],["d-e13-market-economic-system",13,"Market economic system","<p>An economic system in which resources are allocated by the price mechanism (the market forces of demand and supply) and land and capital are privately owned.</p>","<p>Consumers decide what is produced; the government's role is small.</p>",0],["d-e14-market-failure",14,"Market failure","<p>When the market forces of demand and supply lead to an inefficient (wrong) allocation of resources.</p>","<p>Too much or too little of a product is produced, or it is not produced at all.</p>",0],["d-e14-private-cost",14,"Private cost","<p>A cost paid by those directly consuming or producing a product.</p>","<p>e.g. a factory's spending on raw materials and wages; the price a smoker pays for cigarettes.</p>",0],["d-e14-external-cost",14,"External cost","<p>A cost imposed on third parties — people not directly involved in consuming or producing the product — who are not compensated.</p>","<p>e.g. pollution from a factory harming local residents; passive smoking.</p>",0],["d-e14-social-cost",14,"Social cost","<p>The total cost of an economic activity to society: private cost + external cost.</p>","",0],["d-e14-private-benefit",14,"Private benefit","<p>A benefit received by those directly consuming or producing a product.</p>","<p>e.g. the higher earnings of a student who gets a degree.</p>",0],["d-e14-external-benefit",14,"External benefit","<p>A benefit enjoyed by third parties who are not directly involved in consuming or producing the product, and who do not pay for it.</p>","<p>e.g. a vaccinated person protects others from disease; an educated worker raises the productivity of colleagues.</p>",0],["d-e14-social-benefit",14,"Social benefit","<p>The total benefit of an economic activity to society: private benefit + external benefit.</p>","",0],["d-e14-merit-good",14,"Merit good","<p>A product that is more beneficial to consumers than they realise, and so would be under-consumed if left to market forces.</p>","<p>It usually gives <strong>external benefits</strong>. e.g. education, healthcare, vaccinations.</p>",0],["d-e14-demerit-good",14,"Demerit good","<p>A product that is more harmful to consumers than they realise, and so would be over-consumed if left to market forces.</p>","<p>It usually gives <strong>external costs</strong>. e.g. cigarettes, alcohol, sugary drinks, gambling.</p>",0],["d-e14-public-good",14,"Public good","<p>A product that is non-rival and non-excludable, so it would not be provided by the market.</p>","<p>It has to be financed by taxation. e.g. street lighting, national defence, flood defences, lighthouses.</p>",0],["d-e14-monopoly",14,"Monopoly","<p>A market with a single supplier of a product.</p>","<p>A monopoly can <strong>restrict supply</strong> to push up the price — a cause of market failure (Chapter 23).</p>",0],["d-e15-mixed-economic-system",15,"Mixed economic system","<p>An economic system in which both the private sector and the public sector play an important role; resources are allocated by the price mechanism and by the government.</p>","",0],["d-e15-maximum-price",15,"Maximum price","<p>A price ceiling set by the government, above which the price is not allowed to rise.</p>","<p>To have an effect it is set <strong>below</strong> the equilibrium price. e.g. rent controls, price caps on basic food or medicines.</p>",0],["d-e15-minimum-price",15,"Minimum price","<p>A price floor set by the government, below which the price is not allowed to fall.</p>","<p>To have an effect it is set <strong>above</strong> the equilibrium price. e.g. guaranteed minimum prices for farmers' crops, minimum prices for alcohol, the national minimum wage (Chapter 18).</p>",0],["d-e15-indirect-tax",15,"Indirect tax","<p>A tax on spending on goods and services.</p>","<p>It raises firms' costs, so supply decreases and the price rises. e.g. GST/VAT, excise duty on tobacco and fuel.</p>",0],["d-e15-subsidy",15,"Subsidy","<p>A payment by the government to producers (or consumers) to encourage the production or consumption of a product.</p>","<p>It lowers costs, so supply increases and the price falls.</p>",0],["d-e15-regulation",15,"Regulation","<p>Rules and laws set by the government to control the behaviour of firms and consumers.</p>","<p>e.g. bans, age limits, pollution limits, safety standards, rules against anti-competitive behaviour.</p>",0],["d-e15-privatisation",15,"Privatisation","<p>The sale or transfer of public sector (government-owned) assets and firms to the private sector.</p>","",0],["d-e15-nationalisation",15,"Nationalisation","<p>Moving the ownership and control of a firm or industry from the private sector to the public sector (government).</p>","",0],["d-e15-direct-provision",15,"Direct provision","<p>When the government itself supplies goods and services, usually free at the point of use and financed by taxation.</p>","<p>e.g. state schools and hospitals, street lighting, defence, roads.</p>",0],["d-e15-quota-on-extraction",15,"Quota (on extraction)","<p>A limit set by the government on the quantity of a product that can be produced, extracted or traded.</p>","<p>e.g. fishing quotas, limits on logging or mining, to protect natural resources.</p>",0],["d-e18-national-minimum-wage-nmw",18,"National minimum wage (NMW)","<p>A minimum wage rate per hour, set by the government for the whole economy, below which employers cannot legally pay workers.</p>","",0],["d-e18-division-of-labour",18,"Division of labour","<p>When workers specialise in particular tasks (worker specialisation).</p>","<p>e.g. on a car assembly line each worker does one task.</p>",0],["d-e19-trade-union",19,"Trade union","<p>An organisation of workers that represents the interests of its members, especially on pay and working conditions.</p>","<p>e.g. a teachers' union, a nurses' union.</p>",0],["d-e20-primary-secondary-and-tertiary",20,"Primary, secondary and tertiary sectors","<p>Primary sector: firms that extract natural resources (agriculture, fishing, forestry, mining).</p><p>Secondary sector: firms that manufacture goods and construct buildings.</p><p>Tertiary sector: firms that provide services.</p>","<p>e.g. a tea plantation (primary), a car factory (secondary), a bank or hotel (tertiary).</p>",0],["d-e20-merger",20,"Merger","<p>When two or more firms join together to form one firm.</p>","<p>A merger is a form of <strong>external growth</strong>; a <strong>takeover</strong> is when one firm buys another.</p>",0],["d-e20-horizontal-merger",20,"Horizontal merger","<p>A merger between firms producing the same product at the same stage of production.</p>","<p>e.g. two car manufacturers; two banks.</p>",0],["d-e20-vertical-merger",20,"Vertical merger","<p>A merger between firms at different stages of production of the same product.</p>","<p><strong>Backwards</strong> — with a supplier (a chocolate maker buys a cocoa farm). <strong>Forwards</strong> — with an outlet nearer the consumer (a brewery buys pubs).</p>",0],["d-e20-conglomerate-merger",20,"Conglomerate merger","<p>A merger between firms producing different, unrelated products.</p>","<p>e.g. a steel firm merging with a hotel chain. Main motive: <strong>diversification</strong> (spreading risk).</p>",0],["d-e20-economies-of-scale",20,"Economies of scale","<p>The fall in average (total) cost of production that results from a firm or industry increasing its scale of production.</p>","<p><strong>Internal</strong> economies come from the firm growing; <strong>external</strong> economies from the industry growing.</p>",0],["d-e20-diseconomies-of-scale",20,"Diseconomies of scale","<p>The rise in average (total) cost of production that results from a firm or industry growing too large.</p>","",0],["d-e21-production",21,"Production","<p>The total output of goods and services produced by the factors of production in a period of time.</p>","",0],["d-e22-total-cost-tc",22,"Total cost (TC)","<p>The total amount spent on all the factors of production used to produce a given output: fixed cost + variable cost.</p>","",0],["d-e22-average-total-cost-atc",22,"Average total cost (ATC)","<p>Total cost divided by output: the cost of producing one unit.</p>","<p>Also called <strong>average cost</strong> or <strong>unit cost</strong>.</p>",0],["d-e22-fixed-cost-fc",22,"Fixed cost (FC)","<p>A cost that does not change with output.</p>","<p>It must be paid even when output is zero. e.g. rent, insurance, loan interest, managers' salaries.</p>",0],["d-e22-average-fixed-cost-afc",22,"Average fixed cost (AFC)","<p>Total fixed cost divided by output.</p>","<p>It <strong>always falls</strong> as output rises (the fixed cost is spread over more units).</p>",0],["d-e22-variable-cost-vc",22,"Variable cost (VC)","<p>A cost that changes directly with output.</p>","<p>e.g. raw materials, energy used in production, wages of hourly paid workers. Zero when output is zero.</p>",0],["d-e22-average-variable-cost-avc",22,"Average variable cost (AVC)","<p>Total variable cost divided by output.</p>","",0],["d-e22-total-revenue-tr",22,"Total revenue (TR)","<p>The total amount of money a firm receives from selling its output: price × quantity sold.</p>","",0],["d-e22-average-revenue-ar",22,"Average revenue (AR)","<p>Total revenue divided by the quantity sold.</p>","<p>When all units are sold at the same price, <strong>AR = price</strong>.</p>",0],["d-e26-government-budget",26,"Government budget","<p>The government's plan of its spending and its revenue (mainly taxation) for a year.</p>","",0],["d-e26-budget-deficit",26,"Budget deficit","<p>When government spending is greater than government revenue.</p>","<p>The gap is financed by <strong>borrowing</strong>, which adds to the national debt.</p>",0],["d-e26-budget-surplus",26,"Budget surplus","<p>When government revenue is greater than government spending.</p>","<p>It can be used to repay debt.</p>",0],["d-e26-fiscal-policy",26,"Fiscal policy","<p>Decisions on government spending and taxation designed to influence the economy (total demand).</p>","",0],["d-e26-direct-tax",26,"Direct tax","<p>A tax on income and wealth.</p>","<p>e.g. income tax, corporation tax, capital gains tax, inheritance tax.</p>",0],["d-e26-progressive-tax",26,"Progressive tax","<p>A tax that takes a larger percentage of the income of the rich than of the poor.</p>","<p>The tax <strong>rate rises as income rises</strong>. e.g. income tax with higher rates for higher incomes.</p>",0],["d-e26-proportional-tax",26,"Proportional tax","<p>A tax that takes the same percentage of income from all taxpayers.</p>","<p>e.g. a flat-rate income tax of 15% for everyone.</p>",0],["d-e26-regressive-tax",26,"Regressive tax","<p>A tax that takes a larger percentage of the income of the poor than of the rich.</p>","<p>e.g. a fixed amount of tax per person; indirect taxes on necessities (a poor and a rich person pay the same tax on a loaf of bread, but it is a bigger share of the poor person's income).</p>",0],["d-e27-money-supply",27,"Money supply","<p>The total amount of money in an economy: notes and coins in circulation plus bank deposits.</p>","",0],["d-e27-monetary-policy",27,"Monetary policy","<p>Decisions by the central bank (or government) on the rate of interest, the money supply and the foreign exchange rate, to influence the economy (total demand).</p>","",0],["d-e28-supply-side-policy",28,"Supply-side policy","<p>Government measures designed to increase aggregate supply (the productive capacity of the economy) by raising the quantity and quality of resources and the efficiency of markets.</p>","",0],["d-e28-deregulation",28,"Deregulation","<p>The removal of rules and regulations, to increase competition and efficiency.</p>","<p>e.g. allowing new firms into airline, telecoms or energy markets.</p>",0],["d-e29-economic-growth",29,"Economic growth","<p>An increase in the real output of goods and services (real GDP) of an economy over time.</p>","<p>In the long run it also means a rise in the economy's productive capacity.</p>",0],["d-e29-gross-domestic-product-gdp",29,"Gross domestic product (GDP)","<p>The total value of all goods and services produced in a country in a year.</p>","",0],["d-e29-real-gdp",29,"Real GDP","<p>GDP adjusted for inflation (measured at constant prices).</p>","<p>It shows the change in the <strong>quantity</strong> of output, not just in prices.</p>",0],["d-e29-recession",29,"Recession","<p>A fall in real GDP for two successive quarters (six months) or more.</p>","<p>i.e. negative economic growth for at least half a year.</p>",0],["d-e30-employment",30,"Employment","<p>Being involved in productive activity for which a payment is received (having a paid job or being self-employed).</p>","",0],["d-e30-unemployment",30,"Unemployment","<p>Being without a job while willing and able to work, and actively seeking work.</p>","",0],["d-e30-full-employment",30,"Full employment","<p>A situation where everyone who is willing and able to work at the current wage has a job — the lowest level of unemployment possible.</p>","<p>It is not zero unemployment: some frictional and seasonal unemployment always exists.</p>",0],["d-e30-frictional-unemployment",30,"Frictional unemployment","<p>Temporary unemployment of workers who are between jobs.</p>","<p>e.g. a graduate searching for a first job; a worker who has left one job and is looking for another (<strong>search</strong> unemployment).</p>",0],["d-e30-structural-unemployment",30,"Structural unemployment","<p>Unemployment caused by long-term changes in the pattern of demand and methods of production, which make some workers' skills no longer needed.</p>","<p>e.g. coal miners when mines close; workers replaced by machines (<strong>technological</strong>); job losses concentrated in one area (<strong>regional</strong>).</p>",0],["d-e30-cyclical-unemployment",30,"Cyclical unemployment","<p>Unemployment caused by a lack of total (aggregate) demand, e.g. in a recession.</p>","<p>Also called demand-deficient unemployment; it rises and falls with the economic cycle.</p>",0],["d-e30-seasonal-unemployment",30,"Seasonal unemployment","<p>Unemployment caused by a fall in demand for labour at particular times of the year.</p>","<p>e.g. tourism workers out of season, farm workers after the harvest, construction workers in the rainy season.</p>",0],["d-e31-inflation",31,"Inflation","<p>A sustained rise in the general price level of goods and services in an economy over time.</p>","<p>The value (purchasing power) of money falls.</p>",0],["d-e31-deflation",31,"Deflation","<p>A sustained fall in the general price level of goods and services in an economy over time.</p>","<p>The inflation rate is <strong>negative</strong>.</p>",0],["d-e31-consumer-prices-index-cpi",31,"Consumer Prices Index (CPI)","<p>A measure of the weighted average of the prices of a representative basket of goods and services bought by households.</p>","<p>It is used to measure inflation.</p>",0],["d-e31-demand-pull-inflation",31,"Demand-pull inflation","<p>Inflation caused by total (aggregate) demand rising faster than the economy's ability to produce (excess demand).</p>","<p>\"Too much money chasing too few goods.\"</p>",0],["d-e31-cost-push-inflation",31,"Cost-push inflation","<p>Inflation caused by rises in firms' costs of production, which firms pass on as higher prices.</p>","<p>e.g. higher wages, oil and raw material prices.</p>",0],["d-e32-real-gdp-per-head",32,"Real GDP per head","<p>Real GDP divided by the population: the average output (income) per person, adjusted for inflation.</p>","<p>Also called real GDP per capita.</p>",0],["d-e32-human-development-index-hdi",32,"Human Development Index (HDI)","<p>A measure of living standards that combines three dimensions: health (life expectancy at birth), education (mean and expected years of schooling) and income (GNI per head at purchasing power parity).</p>","<p>It ranges from 0 to 1; the closer to 1, the higher the level of human development. Published by the United Nations (UNDP).</p>",0],["d-e33-absolute-poverty",33,"Absolute poverty","<p>A situation where people's income is too low to meet their basic needs for survival (food, clean water, shelter, clothing).</p>","<p>Measured by the World Bank's international poverty line (about $3 a day).</p>",0],["d-e33-relative-poverty",33,"Relative poverty","<p>A situation where people are poor compared with others in their country: their income is too low to enjoy the average standard of living there.</p>","<p>Often measured as income below <strong>60% of the median</strong> income.</p>",0],["d-e34-birth-rate",34,"Birth rate","<p>The number of live births per 1000 of the population in a year.</p>","",0],["d-e34-death-rate",34,"Death rate","<p>The number of deaths per 1000 of the population in a year.</p>","",0],["d-e34-immigration-and-emigration",34,"Immigration and emigration","<p>Immigration: people coming into a country to live.</p><p>Emigration: people leaving a country to live in another country.</p>","",0],["d-e34-net-migration",34,"Net migration","<p>The difference between the number of immigrants and the number of emigrants: immigration minus emigration.</p>","<p>Positive = <strong>net immigration</strong>; negative = <strong>net emigration</strong>.</p>",0],["d-e34-optimum-population",34,"Optimum population","<p>The size of population that maximises a country's output (real GDP) per head, with its existing resources.</p>","<p>Below it the country is <strong>under-populated</strong>; above it, <strong>over-populated</strong>.</p>",0],["d-e36-specialisation-by-country",36,"Specialisation by country","<p>When a country concentrates on producing the goods and services it is best at (most efficient at, or can produce at the lowest cost) and trades to obtain other products.</p>","<p>e.g. India — IT services, generic medicines; Saudi Arabia — oil; Bangladesh — garments; Switzerland — watches and financial services.</p>",0],["d-e37-free-trade",37,"Free trade","<p>International trade without any restrictions such as tariffs, quotas or subsidies.</p>","",0],["d-e37-globalisation",37,"Globalisation","<p>The process by which the world's economies are becoming more closely connected through trade, investment, migration, technology and culture.</p>","",0],["d-e37-multinational-company-mnc",37,"Multinational company (MNC)","<p>A company that has its headquarters in one country and produces (operates) in more than one country.</p>","<p>e.g. Toyota, Unilever, Tata. The <strong>home</strong> country is where it is based; the <strong>host</strong> country is where it sets up.</p>",0],["d-e37-tariff",37,"Tariff","<p>A tax on imports.</p>","<p>It raises the price of imported products.</p>",0],["d-e37-import-quota",37,"Import quota","<p>A limit on the quantity (or value) of a product that can be imported.</p>","",0],["d-e37-embargo",37,"Embargo","<p>A ban on imports from (or exports to) a particular country, or of a particular product.</p>","",0],["d-e37-infant-sunrise-industry",37,"Infant (sunrise) industry","<p>A new industry with relatively low output and high average costs, which cannot yet compete with established foreign firms.</p>","",0],["d-e37-dumping",37,"Dumping","<p>Selling products in a foreign market at a price below the cost of production (or below the price in the home market).</p>","",0],["d-e38-foreign-exchange-rate",38,"Foreign exchange rate","<p>The price of one currency in terms of another currency.</p>","<p>e.g. $1 = ₹85 (so ₹1 ≈ $0.012).</p>",0],["d-e38-floating-exchange-rate",38,"Floating exchange rate","<p>An exchange rate that is determined by the market forces of demand for and supply of the currency.</p>","",0],["d-e38-appreciation",38,"Appreciation","<p>A rise in the value of a floating exchange rate.</p>","<p>Each unit of the currency buys <strong>more</strong> foreign currency. e.g. $1 = ₹85 → $1 = ₹80 is an appreciation of the rupee.</p>",0],["d-e38-depreciation",38,"Depreciation","<p>A fall in the value of a floating exchange rate.</p>","<p>Each unit buys <strong>less</strong> foreign currency. e.g. $1 = ₹85 → $1 = ₹90 is a depreciation of the rupee.</p>",0],["d-e39-current-account",39,"Current account","<p>The part of the balance of payments that records trade in goods, trade in services, primary income and secondary income.</p>","",0],["d-e39-trade-in-goods",39,"Trade in goods","<p>Exports and imports of physical (tangible) products.</p>","<p>e.g. India's exports of refined petroleum, medicines and gems; imports of crude oil and gold. Its balance is the <strong>visible balance</strong> (balance of trade in goods).</p>",0],["d-e39-trade-in-services",39,"Trade in services","<p>Exports and imports of services (intangible products).</p>","<p>e.g. IT services, tourism, banking, insurance, transport. A foreign tourist spending in India is an <strong>export</strong> of services.</p>",0],["d-e39-primary-income",39,"Primary income","<p>Income earned from abroad as wages by people working in other countries, and investment income (profits, interest and dividends) flowing into and out of the country.</p>","<p>e.g. profits sent home by a foreign MNC in India are a primary income <strong>outflow</strong>.</p>",0],["d-e39-secondary-income",39,"Secondary income","<p>Transfers of money between residents and non-residents that are not in return for goods, services or factors of production.</p>","<p>e.g. <strong>workers' remittances</strong>, foreign aid, gifts, payments to international organisations.</p>",0],["d-e39-current-account-deficit-and-su",39,"Current account deficit and surplus","<p>A current account deficit is when more money leaves the country than comes in on the current account (outflows &gt; inflows).</p><p>A current account surplus is when more money comes in than leaves (inflows &gt; outflows).</p>","",0]]});
